int compareVersions(const char* a, const char* b) {
    while (*a || *b) {
        long x = 0, y = 0;
        while (*a && *a != '.') x = x * 10 + (*a++ - '0');
        while (*b && *b != '.') y = y * 10 + (*b++ - '0');
        if (x != y) return x < y ? -1 : 1;
        if (*a) a++;
        if (*b) b++;
    }
    return 0;
}

static int byVersion(const void* x, const void* y) {
    return compareVersions(*(const char* const*)x, *(const char* const*)y);
}

void sortVersions(const char** versions, int n) {
    qsort(versions, n, sizeof(char*), byVersion);
}

