static int target;

static int byDistance(const void* x, const void* y) {
    int a = *(const int*)x, b = *(const int*)y;
    int da = abs(a - target), db = abs(b - target);
    if (da != db) return (da > db) - (da < db);
    return (a > b) - (a < b);
}

void byCloseness(int* nums, int n, int t) {
    target = t;
    qsort(nums, n, sizeof(int), byDistance);
}
